import{_ as l,c as e,o as a,a2 as t}from"./chunks/framework.CzULAunO.js";const u=JSON.parse('{"title":"安卓端到端加密聊天软件","description":"","frontmatter":{},"headers":[],"relativePath":"docs/general-skills/加密通讯.md","filePath":"docs/general-skills/加密通讯.md","lastUpdated":1766652908000}'),i={name:"docs/general-skills/加密通讯.md"};function o(n,r,s,g,h,p){return a(),e("div",null,r[0]||(r[0]=[t('<h1 id="安卓端到端加密聊天软件" tabindex="-1"><strong>安卓端到端加密聊天软件</strong> <a class="header-anchor" href="#安卓端到端加密聊天软件" aria-label="Permalink to &quot;**安卓端到端加密聊天软件**&quot;">​</a></h1><h2 id="为什么要使用端到端加密聊天软件" tabindex="-1">为什么要使用端到端加密聊天软件 <a class="header-anchor" href="#为什么要使用端到端加密聊天软件" aria-label="Permalink to &quot;为什么要使用端到端加密聊天软件&quot;">​</a></h2><ol><li>避免网络审查和监控 <ul><li>WeChat，QQ 会访问你的聊天链接，如果访问到订阅链接，人身安全存疑。</li></ul></li><li>保护隐私与个人数据</li><li>防范黑客攻击和信息泄露 <ul><li>国内外许多聊天软件出现过大面积信息泄露</li></ul></li><li>应对身份盗窃和网络诈骗 <ul><li>不好说，毕竟 Telegram 是出了名的骗子多～</li></ul></li><li>数据安全的法律保障</li><li>等等……</li></ol><h2 id="telegram" tabindex="-1"><strong>Telegram</strong> <a class="header-anchor" href="#telegram" aria-label="Permalink to &quot;**Telegram**&quot;">​</a></h2><p><img src="https://ooo.0x0.ooo/2024/10/22/ODdJaK.jpg" alt="ODdJaK.jpg"></p><p>Telegram 是最广为认知的端到端加密聊天通讯软件，部分开发的源代码促进其生态的繁荣</p><ul><li><a href="https://t.me" target="_blank" rel="noreferrer">Telegram 官方下载</a></li><li><strong>Telegram X</strong>（==推荐==，仅 Android） <ul><li><a href="https://github.com/TGX-Android/Telegram-X/releases/tag/v0.26.9.1730" target="_blank" rel="noreferrer">Telegram X</a></li></ul></li></ul><p>PS：真的很繁荣，还有众多第三方构建的版本</p><ul><li><p>Nekogram（Android）</p><ul><li><a href="https://github.com/Nekogram/Nekogram/releases" target="_blank" rel="noreferrer">Nekogram</a></li></ul></li><li><p>NULLgram（Android）</p><ul><li><a href="https://github.com/qwq233/Nullgram/releases" target="_blank" rel="noreferrer">Nullgram</a></li></ul></li><li><p>Nagram（Android）</p><ul><li><a href="https://github.com/NextAlone/Nagram/releases" target="_blank" rel="noreferrer">Nagram</a></li></ul></li><li><p>Forkgram</p><ul><li><a href="https://github.com/forkgram/TelegramAndroid/releases" target="_blank" rel="noreferrer">Forkgram</a></li></ul></li><li><p>Cherrygram（Android）</p><ul><li><a href="https://github.com/arsLan4k1390/Cherrygram/releases" target="_blank" rel="noreferrer">Cherrygram</a></li></ul></li><li><p>Mercurygram</p><ul><li><a href="https://github.com/Mercurygram/Mercurygram/releases" target="_blank" rel="noreferrer">Mercurygram</a></li></ul></li><li><p>MDgram（Android）</p><ul><li><a href="https://mdgram.dev/download-mdgram/" target="_blank" rel="noreferrer">MDgram</a></li></ul></li><li><p>Swiftgram（iOS）</p><ul><li><a href="https://github.com/Swiftgram/Telegram-iOS" target="_blank" rel="noreferrer">Swiftgram</a></li></ul></li><li><p>Turrit（Android/iOS）</p><ul><li><a href="https://iturrit.com/zh/" target="_blank" rel="noreferrer">Turrit</a></li></ul></li><li><p>Nicegram（Android、iOS、MacOS）</p><ul><li><a href="https://nicegram.app/" target="_blank" rel="noreferrer">Nicegram</a></li></ul></li><li><p>Unigram（Windows）</p><ul><li><a href="https://github.com/UnigramDev/Unigram" target="_blank" rel="noreferrer">Unigram</a></li></ul></li><li><p>materialgram（Windows）</p><ul><li><a href="https://github.com/kukuruzka165/materialgram/releases" target="_blank" rel="noreferrer">materialgram</a></li></ul></li><li><p>64gram（Windows、Linux、MacOS ）</p><ul><li><a href="https://github.com/TDesktop-x64/tdesktop/releases" target="_blank" rel="noreferrer">64gram</a></li></ul></li><li><p>iMe Messenger (Windows, Linux, MacOS, Android, iOS)</p><ul><li><a href="https://www.imem.app/" target="_blank" rel="noreferrer">iMe Messenger</a></li></ul></li></ul><p>等等众多第三方 telegram 客户端</p><h2 id="martix" tabindex="-1"><strong>Martix</strong> <a class="header-anchor" href="#martix" aria-label="Permalink to &quot;**Martix**&quot;">​</a></h2><img src="https://ooo.0x0.ooo/2024/10/22/ODdHRL.jpg" alt="ODdHRL.jpg" width="204" height="145" class="jop-noMdConv"><p><strong>什么是 Martix？</strong><br> Matrix 是一个开源的、分布式的即时通讯协议，旨在提供跨平台的实时通信服务。</p><ul><li><strong>Element X</strong>（==推荐==） <ul><li>Martix 官方 Android 应用，功能强大。</li><li><a href="https://github.com/element-hq/element-x-android/releases/tag/v0.7.0" target="_blank" rel="noreferrer">Element X</a><br><img src="https://ooo.0x0.ooo/2024/10/22/ODdQyt.png" alt="ODdQyt.png" width="80" height="80" class="jop-noMdConv"></li></ul></li><li><strong>Fluffy Chat</strong><ul><li>毛茸茸且简洁的 Martix 客户端。</li><li><a href="https://fluffychat.im/" target="_blank" rel="noreferrer">fluffychat</a><br><img src="https://ooo.0x0.ooo/2024/10/22/ODdGUX.png" alt="ODdGUX.png" width="80" height="80" class="jop-noMdConv"></li></ul></li></ul><h2 id="其他去中心化-端到端加密聊天软件" tabindex="-1">其他<strong>去中心化，端到端加密</strong>聊天软件 <a class="header-anchor" href="#其他去中心化-端到端加密聊天软件" aria-label="Permalink to &quot;其他**去中心化，端到端加密**聊天软件&quot;">​</a></h2><ul><li><strong>什么是端到端加密（ETE）？</strong>：确保只有通信的两端——即发送方和接收方——能够解密并查看消息内容。中间的服务器、网络提供商或任何第三方都无法访问加密的消息内容，即使数据在传输过程中被拦截，也无法解读其内容。</li><li><strong>什么是去中心化？</strong>：不依赖中心服务器，而是基于 P2P（点对点）网络 进行通信。每个设备都是一个节点，直接与其他设备通信，这意味着没有任何中央机构可以监控或存储你的数据。</li><li><strong>Session</strong>（==推荐==） <ul><li>更为先进，极简的去中心化，端到端加密工具</li><li><a href="https://apt.izzysoft.de/fdroid/index/apk/network.loki.messenger" target="_blank" rel="noreferrer">Session</a></li><li><img src="https://ooo.0x0.ooo/2024/10/22/ODd9jc.jpg" alt="ODd9jc.jpg" width="80" height="80" class="jop-noMdConv"></li></ul></li><li><strong>ArcaneChat</strong>（==推荐==） <ul><li>多功能去中心化，端到端加密工具，独树一帜涵盖了 AI</li><li><a href="https://apt.izzysoft.de/fdroid/index/apk/chat.delta.lite" target="_blank" rel="noreferrer">Arcane Chat</a></li><li><img src="https://ooo.0x0.ooo/2024/10/22/ODd2Wr.png" alt="ODd2Wr.png" width="81" height="77" class="jop-noMdConv"></li></ul></li><li><strong>Jami</strong><ul><li>P2P 点对点通信工具</li><li><a href="https://jami.net/" target="_blank" rel="noreferrer">Jami</a></li><li><img src="https://ooo.0x0.ooo/2024/10/22/ODdcaj.png" alt="ODdcaj.png" width="80" height="80" class="jop-noMdConv"></li></ul></li><li><strong>SimpleX</strong><ul><li>P2P 点对点通信工具</li><li><a href="https://simplex.chat/" target="_blank" rel="noreferrer">SimpleX</a></li><li><img src="https://ooo.0x0.ooo/2024/10/22/ODdVIY.png" alt="ODdVIY.png" width="80" height="80" class="jop-noMdConv"></li></ul></li></ul><h2 id="为什么不列出所有端到端加密聊天软件" tabindex="-1">为什么不列出所有端到端加密聊天软件 <a class="header-anchor" href="#为什么不列出所有端到端加密聊天软件" aria-label="Permalink to &quot;为什么不列出所有端到端加密聊天软件&quot;">​</a></h2><ul><li>由于开源软件开发成本，技术限制，许多软件使用了同一种加密技术以及交互方法，许多软件只是外壳不同，故只挑出最流行，使用最棒的软件。</li></ul><p>FOLLOW ME IN: <a href="https://linux.do/u/user695/summary" target="_blank" rel="noreferrer">https://linux.do/u/user695/summary</a></p><p>原文地址：</p><p><a href="https://linux.do/t/topic/239207" target="_blank" rel="noreferrer">https://linux.do/t/topic/239207</a></p><p>向我申请邀请码：</p><p><a href="mailto:jay20070220@gmail.com" target="_blank" rel="noreferrer">jay20070220@gmail.com</a></p>',23)]))}const d=l(i,[["render",o]]);export{u as __pageData,d as default};
